function validate([intervals]) {
  if (!Array.isArray(intervals) || intervals.length < 1 || intervals.length > 20000) return 'intervals needs 1 to 20000 pairs.';
  const seen = new Set();
  for (const pair of intervals) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each interval is a pair [start, end].';
    const [start, end] = pair;
    if (!Number.isInteger(start) || !Number.isInteger(end)) return 'Starts and ends are whole numbers.';
    if (start < -1000000 || end > 1000000 || start > end) return 'Each interval needs -10^6 <= start <= end <= 10^6.';
    if (seen.has(start)) return 'No two intervals may share a start.';
    seen.add(start);
  }
  return null;
}

