function findRightInterval(intervals) {
  return intervals.map(([, end]) => {
    let bestIndex = -1;
    intervals.forEach(([start], j) => {
      if (start >= end && (bestIndex === -1 || start < intervals[bestIndex][0])) bestIndex = j;
    });
    return bestIndex;
  });
}

