function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 8);
  const span = large ? 1000000 : 12;
  const reach = large ? 4000 : 6;
  const used = new Set();
  const intervals = [];
  while (intervals.length < n) {
    const start = Math.floor(rand() * (2 * span + 1)) - span;
    if (used.has(start)) continue;
    used.add(start);
    const end = Math.min(span, start + Math.floor(rand() * (reach + 1)));
    intervals.push([start, end]);
  }
  return [intervals];
}
